mapper.update:
UPDATE seckill_order
SET status = #{status}, updated_at = #{updatedAt}, update_by = #{updateBy}
WHERE id = #{id}

mapper.delete:
DELETE FROM seckill_order
WHERE order_id = #{orderId}
  AND status = 1

mapper.select:
SELECT user_id
FROM seckill_order
WHERE seckill_goods_id = #{seckillGoodsId}
